  { label: 'Total Halaman', value: `${data.value.stats.pages} Halaman`, note: `${data.value.stats.sections} section`, icon: FileText, box: 'bg-sky-50 text-sky-600' },
  { label: 'File Media', value: `${data.value.stats.media} Item`, note: 'Media website', icon: ImageIcon, box: 'bg-amber-50 text-amber-600' },
